  function progressDots(flow, currentStep){

    const idx = flow.steps.indexOf(currentStep);

    return `<div class="progress-dots">${flow.steps.map((s,i)=>{

      let cls = "";

      if (i < idx) cls = "done";

      else if (i === idx) cls = "current";

      return `<span class="${cls}"></span>`;

    }).join("")}</div>`;

  }

/* ============================================================

   TELA 1 — CONVITE (com botão "não" fujão e foto polaroid)

   ============================================================ */

  const noMessagesEscalating = [

    ["não vale 😏","tenta de novo 🙈","hmm, não foi dessa vez 💫"],

    ["quase! kkk 😅","esse botão não existe pra você 💗","segue tentando 😌"],

    ["kkkkk desiste 🙈","não tem chance 💗","olha só o 'sim' ali do lado 👉"],

    ["eu sei que você me ama 🥹","só aperta o 'sim' logo 😩💗","tô esperando... 🥺"],

    ["tá bom, eu insisto: SIM 💗","você já sabe a resposta certa 😌","kkkkkk aperta o outro"]

  ];

  function renderInvite(){

     render(` 

      <span class="eyebrow">um recadinho pra você</span>

      <div class="polaroid">

        <img src="${COUPLE_PHOTO}" alt="a gente">

        <span>nós dois 💕</span>

      </div>

      <h1>Ludmila, você quer sair comigo? 🥹💌</h1>

      <p class="sub">psss... o botão "não" é meio tímido</p>

      <div class="invite-stage" id="inviteStage">

        <button class="btn btn-yes" id="yesBtn" style="position:absolute; left:50%; top:75%; transform:translate(-50%,-50%);">Sim ✨</button>

        <button class="btn btn-no" id="noBtn" style="left:50%; top:15%; transform:translate(-50%,-50%);">Não</button>

      </div>

    `);

    const stage = document.getElementById("inviteStage");

    const noBtn = document.getElementById("noBtn");

    const yesBtn = document.getElementById("yesBtn");

    function dodge(){

      state.noAttempts++;

      const stageRect = stage.getBoundingClientRect();

      const btnW = noBtn.offsetWidth, btnH = noBtn.offsetHeight;

      const maxX = Math.max(stageRect.width - btnW, 10);

      const maxY = Math.max(stageRect.height - btnH, 10);

      const newX = Math.random()*maxX + btnW/2;

      const newY = Math.random()*maxY + btnH/2;

      noBtn.style.left = newX + "px";

      noBtn.style.top = newY + "px";

      const tier = Math.min(Math.floor(state.noAttempts/2), noMessagesEscalating.length-1);

      const pool = noMessagesEscalating[tier];

      noBtn.textContent = pool[Math.floor(Math.random()*pool.length)];

      playTone(300, 0.1, "triangle");

    }

    noBtn.addEventListener("mouseenter", dodge);

    noBtn.addEventListener("pointerdown", (e)=>{ e.preventDefault(); dodge(); });

    noBtn.addEventListener("touchstart", (e)=>{ e.preventDefault(); dodge(); }, {passive:false});

    noBtn.addEventListener("click", (e)=>{ e.preventDefault(); dodge(); });

    yesBtn.addEventListener("click", ()=>{

      launchConfetti();

      playBell();

      setTimeout(renderTypeSelect, 300);

    });

  }

